#!/bin/sh
# Writes s9x7z_prefix.h: every external symbol the vendored LZMA SDK files define, renamed to s9x7z_<name>.
# Run from this folder after updating the SDK files: sh make_prefix.sh > s9x7z_prefix.h
set -e
tmp=$(mktemp -d)
for f in *.c; do
	${CC:-cc} -O1 -DZ7_ST -DZ7_PPMD_SUPPORT -DZ7_EXTRACT_ONLY -c -o "$tmp/${f%.c}.o" "$f"
done
echo "// Generated by make_prefix.sh: the LZMA SDK's external symbols, renamed so this copy can't meet another"
echo "// LZMA SDK copy linked into the same program (a libchdr, say). Included first in every file that uses it."
echo "#pragma once"
nm -g --defined-only "$tmp"/*.o | awk 'NF==3{print $3}' | sort -u | awk '{printf "#define %s s9x7z_%s\n", $1, $1}'
rm -rf "${tmp:?}"
